cat > /tmp/analyze.pl <<'EOF'
#!/usr/bin/perl
use strict; use warnings;
open(my $fh, '<:raw', '/app/vocab.bpe') or die;
my @lines = <$fh>; close $fh;
chomp @lines;
print "total lines: ", scalar(@lines), "\n";
my %fields; my %bad;
for my $l (@lines[1..$#lines]) {
    my @f = split(' ', $l, -1);
    $fields{scalar(@f)}++;
    $bad{$l} = 1 if !($l =~ /^(\S+) (\S+)( \d+)?$/);
}
print "field counts: ", join(", ", map { "$_=>$fields{$_}" } sort {$a<=>$b} keys %fields), "\n";
print "bad lines: ", scalar(keys %bad), "\n";
print "first bad: $bad{$_}\n" for (keys %bad)[0..($#lines>0?2:-1)];

# codepoint ranges
my %cp;
for my $l (@lines[1..$#lines]) {
    my @f = split(' ', $l, 2);
    for my $t (@f) {
        while ($t =~ /\x{}/g) {} # noop
    }
}
# manual UTF-8 decode of codepoints
sub cps {
    my ($s) = @_;
    my @out;
    my @b = unpack('C*', $s);
    my $i = 0;
    while ($i < @b) {
        my $c = $b[$i++];
        my $cp;
        if ($c < 0x80) { $cp = $c; }
        elsif (($c & 0xE0) == 0xC0) { $cp = (($c & 0x1F) << 6) | ($b[$i++] & 0x3F); }
        elsif (($c & 0xF0) == 0xE0) { $cp = (($c & 0x0F) << 12) | (($b[$i++] & 0x3F) << 6) | ($b[$i++] & 0x3F); }
        else { $cp = (($c & 0x07) << 18) | (($b[$i++] & 0x3F) << 12) | (($b[$i++] & 0x3F) << 6) | ($b[$i++] & 0x3F); }
        push @out, $cp;
    }
    return @out;
}
my %range; my %allcp;
for my $l (@lines[1..$#lines]) {
    for my $t (split(' ', $l, 2)) {
        for my $c (cps($t)) {
            $allcp{$c}++;
            if    ($c >= 0xF000 && $c <= 0xF01F) { $range{F}++; }
            elsif ($c == 0x0120) { $range{space}++; }
            elsif ($c >= 0x0190 && $c <= 0x01C9) { $range{lat}++; }
            elsif ($c >= 0x02D0 && $c <= 0x03AF) { $range{ipa}++; }
            elsif ($c >= 0x21 && $c <= 0x7E) { $range{ascii}++; }
            else { $range{OTHER}++; $range{other:$c}++; }
        }
    }
}
print "cp ranges: ", join(", ", map { "$_=$range{$_}" } sort keys %range), "\n";
print "distinct cps: ", scalar(keys %allcp), "\n";

# build vocab
sub byte2utf8 {
    my ($b) = @_;
    if ($b < 32) { return chr(0xF000+$b); }
    return chr(0x120) if $b == 32;
    return chr($b) if $b <= 126;
    return chr(0x190 + $b - 127) if $b <= 167;
    return chr(0x2D0 + $b - 168);
}
my %vocab;
for my $b (0..255) { $vocab{byte2utf8($b)} = $b; }
my $id = 256;
my $dups = 0;
for my $l (@lines[1..$#lines]) {
    my ($u, $v) = split(' ', $l, 2);
    my $new = "$u$v";
    if (exists $vocab{$new}) { $dups++; }
    else { $vocab{$new} = $id++; }
}
print "dups: $dups, unique tokens: ", scalar(keys %vocab), ", last id: ", $id-1, "\n";
# max id and holes
my %seen; $seen{$_}++ for values %vocab;
my @holes; for my $i (0..$id-1) { push @holes, $i unless $seen{$i}; }
print "holes: ", join(",", @holes[0..49]), (scalar(@holes)>50?"...":"")."\n" if @holes;
EOF
perl /tmp/analyze.pl

