#!/usr/bin/perl
use strict; use warnings;
sub slurp { open(my $f,'<:raw',$_[0]) or die; local $/; my $d=<$f>; close $f; return $d; }
my $a = slurp('/app/vocab.bpe');
my $b = slurp('/tmp/merges.txt');
my @A = split("\n", $a); my @B = split("\n", $b);
print "lines: ", scalar(@A), " vs ", scalar(@B), "\n";
sub cpstr { my ($s)=@_; my @b=unpack('C*',$s); my $i=0; my @o;
  while($i<@b){ my $c=$b[$i++]; my $cp;
    if($c<0x80){$cp=$c} elsif(($c&0xE0)==0xC0){$cp=(($c&0x1F)<<6)|($b[$i++]&0x3F)}
    elsif(($c&0xF0)==0xE0){$cp=(($c&0x0F)<<12)|(($b[$i++]&0x3F)<<6)|($b[$i++]&0x3F)}
    else{$cp=(($c&0x07)<<18)|(($b[$i++]&0x3F)<<12)|(($b[$i++]&0x3F)<<6)|($b[$i++]&0x3F)}
    push @o,$cp;}
  return @o; }
my $same=0; my $diff=0; my @ex;
for my $i (0..$#B) {
    last if $i > $#A;
    if ($A[$i] eq $B[$i]) { $same++; next; }
    $diff++;
    my @ta = split(' ', $A[$i],2); my @tb = split(' ', $B[$i],2);
    my $ok = (@ta==2 && @tb==2);
    if ($ok) {
        for my $k (0,1) {
            my @ca = cpstr($ta[$k]); my @cb = cpstr($tb[$k]);
            $ok = 0 if @ca != @cb;
        }
    }
    push @ex, "$i: [$A[$i]] vs [$B[$i]] same_len=$ok" unless @ex>9;
}
print "identical: $same, differing: $diff\n";
print "$_\n" for @ex;
# build mapping canon cp -> app cp
my %map; my %conflict;
for my $i (0..$#B) { last if $i>$#A; next if $A[$i] eq $B[$i];
  my @ta=split(' ',$A[$i],2); my @tb=split(' ',$B[$i],2);
  next unless @ta==2 && @tb==2;
  for my $k (0,1){
    my @ca=cpstr($ta[$k]); my @cb=cpstr($tb[$k]);
    next unless @ca==@cb;
    for my $j (0..$#ca){
        if(exists $map{$cb[$j]} && $map{$cb[$j]} != $ca[$j]){ $conflict{$cb[$j]} = "$map{$cb[$j]} vs $ca[$j]"; }
        $map{$cb[$j]} = $ca[$j];
    }
  }
}
print "mapping entries: ", scalar(keys %map), ", conflicts: ", scalar(keys %conflict), "\n";
print "conflict: $_: $conflict{$_}\n" for (sort keys %conflict)[0..9];
# print mapping for the 0x190-0x1C9 and 0x2D0-0x3AF ranges
my @r1 = grep { $_>=0x190 && $_<=0x1C9 } keys %map;
my @r2 = grep { $_>=0x2D0 && $_<=0x3AF } keys %map;
printf "0x190-0x1C9 mapped: %d/%d: ", scalar(@r1), 41;
printf "%04x->%04x ", $_, $map{$_} for @r1; print "\n";
printf "0x2D0-0x3AF mapped: %d/%d: ", scalar(@r2), 88;
printf "%04x->%04x ", $_, $map{$_} for @r2; print "\n";
EOF
