#!/usr/bin/perl
use strict; use warnings;
# --- parse flat JSON object: {"str": int, ...}
open(my $fh, '<:raw', '/tmp/vocab.json') or die;
local $/; my $d = <$fh>; close $fh;
my %vocab;
my $i = 0; my $n = length($d);
die "no opening brace" unless substr($d,0,1) eq '{';
$i = 1;
sub parse_string {
    my ($s, \$pos) = @_;
    die "expected quote" unless substr($s,$pos,1) eq '"';
    $pos++;
    my $out = '';
    while ($pos < length($s)) {
        my $c = substr($s,$pos,1);
        if ($c eq '"') { $pos++; last; }
        if ($c eq '\\') {
            my $e = substr($s,$pos+1,1); $pos += 2;
            if    ($e eq '"')  { $out .= '"'; }
            elsif ($e eq '\\') { $out .= '\\'; }
            elsif ($e eq '/')  { $out .= '/'; }
            elsif ($e eq 'n')  { $out .= "\n"; }
            elsif ($e eq 'r')  { $out .= "\r"; }
            elsif ($e eq 't')  { $out .= "\t"; }
            elsif ($e eq 'b')  { $out .= "\b"; }
            elsif ($e eq 'f')  { $out .= "\f"; }
            elsif ($e eq 'u')  { my $h = substr($s,$pos,4); $pos += 4; my $cp = hex($h);
                # surrogate pairs
                if ($cp >= 0xD800 && $cp <= 0xDBFF && substr($s,$pos,2) eq '\u') {
                    my $h2 = hex(substr($s,$pos+2,4)); $pos += 6;
                    $cp = 0x10000 + (($cp - 0xD800) << 10) + ($h2 - 0xDC00);
                }
                $out .= chr($cp);
            } else { die "bad escape $e"; }
        } else { $out .= $c; $pos++; }
    }
    return $out;
}
while ($i < $n) {
    while ($i < $n && $d =~ /\s/) { $i++; last if $d =~ /\s/; }
    last if substr($d,$i,1) eq '}';
    my $k = parse_string($d, \$i);
    # skip to :
    while ($d =~ /\s/) { $i++; last if $d =~ /\s/; }
    die "no colon at $i" unless substr($d,$i,1) eq ':';
    $i++;
    while ($d =~ /\s/) { $i++; last if $d =~ /\s/; }
    my $v = substr($d,$i); $v =~ /^(\d+)/ or die "no int at $i: $v";
    $i += length($1);
    $vocab{$k} = $1 + 0;
    while ($d =~ /\s/) { $i++; last if $d =~ /\s/; }
    die "no comma at $i" unless substr($d,$i,1) eq ',';
    $i++;
}
print "vocab entries: ", scalar(keys %vocab), "\n";
# check ids
my %seenid; my $maxid = -1;
for my $v (values %vocab) { $seenid{$v}++; $maxid = $v if $v > $maxid; }
my @dupid; push @dupid, $_ for grep { $seenid{$_} > 1 } keys %seenid;
print "max id: $maxid, dup ids: ", join(",", @dupid[0..4]), "\n";
my @holes; for my $x (0..$maxid) { push @holes, $x unless $seenid{$x}; }
print "holes: ", scalar(@holes), ": ", join(",", @holes[0..59]), (scalar(@holes)>60?" ...":""), "\n";

# codepoints
sub cps {
    my ($s) = @_; my @out; my @b = unpack('C*', $s); my $p = 0;
    while ($p < @b) {
        my $c = $b[$p++]; my $cp;
        if ($c < 0x80) { $cp = $c; }
        elsif (($c & 0xE0) == 0xC0) { $cp = (($c & 0x1F) << 6) | ($b[$p++] & 0x3F); }
        elsif (($c & 0xF0) == 0xE0) { $cp = (($c & 0x0F) << 12) | (($b[$p++] & 0x3F) << 6) | ($b[$p++] & 0x3F); }
        else { $cp = (($c & 0x07) << 18) | (($b[$p++] & 0x3F) << 12) | (($b[$p++] & 0x3F) << 6) | ($b[$p++] & 0x3F); }
        push @out, $cp;
    }
    return @out;
}
# single-char tokens
my %base; my $nbase = 0;
for my $t (keys %vocab) {
    my @c = cps($t);
    if (@c == 1) { $base{$c[0]} = $vocab{$t}; $nbase++; }
}
print "single-char tokens: $nbase\n";
my @blist = sort { $a <=> $b } keys %base;
# print mapping byte(id) -> cp for all 256
my @mapout;
for my $b (0..255) {
    # find token with this id
    my ($t) = grep { $vocab{$_} == $b } keys %vocab;
    if (!defined $t) { push @mapout, "$b=???"; }
    else { my @c = cps($t); push @mapout, sprintf "%b=%04x", $b, $c[0]; }
}
for my $i (0..255) {
    print $mapout[$i], " ";
    print "\n" if ($i+1) % 32 == 0;
}
EOF
